1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
libceph: Fix potential out-of-bounds access in
 osdmap_decode()

When decoding osd_state and osd_weight from an incoming osdmap in
osdmap_decode(), both are decoded for each osd, i.e., map->max_osd
times. The ceph_decode_need() check only accounts for
sizeof(*map->osd_weight) once. This can potentially result in an
out-of-bounds memory access if the incoming message is corrupted such
that the max_osd value exceeds the actual content of the osdmap message.

This patch fixes the issue by changing the corresponding part in the
ceph_decode_need() check to account for
map->max_osd*sizeof(*map->osd_weight).

Cc: stable@vger.kernel.org
Fixes: dcbc919a5dc8 ("libceph: switch osdmap decoding to use ceph_decode_entity_addr")
Signed-off-by: Raphael Zimmer <raphael.zimmer@tu-ilmenau.de>
Reviewed-by: Ilya Dryomov <idryomov@gmail.com>
Signed-off-by: Ilya Dryomov <idryomov@gmail.com>

Here is the root cause:
The ceph_decode_need() check in osdmap_decode() only allocated space for a single osd_weight entry instead of map->max_osd entries, causing a potential out-of-bounds memory access when decoding corrupted osdmap messages with a large max_osd value.

Here is the patch:
  */
 static int osdmap_decode(void **p, void *end, bool msgr2,
 			 struct ceph_osdmap *map)
 {
 	u8 struct_v;
 	u32 epoch = 0;
 	void *start = *p;
 	u32 max;
 	u32 len, i;
 	int err;

 	dout("%s %p to %p len %d\n", __func__, *p, end, (int)(end - *p));

 	err = get_osdmap_client_data_v(p, end, "full", &struct_v);
 	if (err)
 		goto bad;

 	/* fsid, epoch, created, modified */
 	ceph_decode_need(p, end, sizeof(map->fsid) + sizeof(u32) +
 			 sizeof(map->created) + sizeof(map->modified), e_inval);
 	ceph_decode_copy(p, &map->fsid, sizeof(map->fsid));
 	epoch = map->epoch = ceph_decode_32(p);
 	ceph_decode_copy(p, &map->created, sizeof(map->created));
 	ceph_decode_copy(p, &map->modified, sizeof(map->modified));

 	/* pools */
 	err = decode_pools(p, end, map);
 	if (err)
 		goto bad;

 	/* pool_name */
 	err = decode_pool_names(p, end, map);
 	if (err)
 		goto bad;

 	ceph_decode_32_safe(p, end, map->pool_max, e_inval);

 	ceph_decode_32_safe(p, end, map->flags, e_inval);

 	/* max_osd */
 	ceph_decode_32_safe(p, end, max, e_inval);

 	/* (re)alloc osd arrays */
 	err = osdmap_set_max_osd(map, max);
 	if (err)
 		goto bad;

 	/* osd_state, osd_weight, osd_addrs->client_addr */
 	ceph_decode_need(p, end, 3*sizeof(u32) +
 			 map->max_osd*(struct_v >= 5 ? sizeof(u32) :
 						       sizeof(u8)) +
-				       sizeof(*map->osd_weight), e_inval);
+			 map->max_osd*sizeof(*map->osd_weight), e_inval);
 	if (ceph_decode_32(p) != map->max_osd)
 		goto e_inval;

 	if (struct_v >= 5) {
 		for (i = 0; i < map->max_osd; i++)
 			map->osd_state[i] = ceph_decode_32(p);
 	} else {
 		for (i = 0; i < map->max_osd; i++)
 			map->osd_state[i] = ceph_decode_8(p);
 	}

 	if (ceph_decode_32(p) != map->max_osd)
 		goto e_inval;

 	for (i = 0; i < map->max_osd; i++)
 		map->osd_weight[i] = ceph_decode_32(p);

 	if (ceph_decode_32(p) != map->max_osd)
 		goto e_inval;

 	for (i = 0; i < map->max_osd; i++) {
 		struct ceph_entity_addr *addr = &map->osd_addr[i];

 		if (struct_v >= 8)
 			err = ceph_decode_entity_addrvec(p, end, msgr2, addr);
 		else
 			err = ceph_decode_entity_addr(p, end, addr);
 		if (err)
 			goto bad;

 		dout("%s osd%d addr %s\n", __func__, i, ceph_pr_addr(addr));
 	}

 	/* pg_temp */
 	err = decode_pg_temp(p, end, map);
 	if (err)
 		goto bad;

 	/* primary_temp */
 	if (struct_v >= 1) {
 		err = decode_primary_temp(p, end, map);
 		if (err)
 			goto bad;
 	}

 	/* primary_affinity */
 	if (struct_v >= 2) {
 		err = decode_primary_affinity(p, end, map);
 		if (err)
 			goto bad;
 	} else {
 		WARN_ON(map->osd_primary_affinity);
 	}

 	/* crush */
 	ceph_decode_32_safe(p, end, len, e_inval);
 	err = osdmap_set_crush(map, crush_decode(*p, min(*p + len, end)));
 	if (err)
 		goto bad;

 	*p += len;
 	if (struct_v >= 3) {
 		/* erasure_code_profiles */
 		ceph_decode_skip_map_of_map(p, end, string, string, string,
 					    e_inval);
 	}

 	if (struct_v >= 4) {
 		err = decode_pg_upmap(p, end, map);
 		if (err)
 			goto bad;

 		err = decode_pg_upmap_items(p, end, map);
 		if (err)
 			goto bad;
 	} else {
 		WARN_ON(!RB_EMPTY_ROOT(&map->pg_upmap));
 		WARN_ON(!RB_EMPTY_ROOT(&map->pg_upmap_items));
 	}

 	/* ignore the rest */
 	*p = end;

 	dout("full osdmap epoch %d max_osd %d\n", map->epoch, map->max_osd);
 	return 0;

 e_inval:
 	err = -EINVAL;
 bad:
 	pr_err("corrupt full osdmap (%d) epoch %d off %d (%p of %p-%p)\n",
 	       err, epoch, (int)(*p - start), *p, start, end);
 	print_hex_dump(KERN_DEBUG, "osdmap: ",
 		       DUMP_PREFIX_OFFSET, 16, 1,
 		       start, end - start, true);
 	return err;
 }



